```csharp
using System;

class MainClass {
  public static void Main (string[] args) {
    // convertir nm en mètres
    double lengthInMeter = 600 * Math.Pow(10, -9);

    // vitesse de la lumière en m/s
    double speedOfLight = 299792458;

    // valeur de la constante de Planck en J s
    double planckConstant = 6.62607004 * Math.Pow(10, -34);

    // calculer l'énergie en joules
    double photonEnergy = (planckConstant * speedOfLight) / lengthInMeter;

    // calculer la valeur de h en utilisant l'énergie du photon
    double h = photonEnergy / speedOfLight;

    // afficher les résultats
    Console.WriteLine("La valeur de la constante de Planck (h) est : " + h.ToString() + " J s");
    Console.WriteLine("L'énergie d'un photon avec une longueur d'onde de 600 nm est : " + photonEnergy.ToString() + " J");
  }
}
```

