     <a-assets>
       <a-asset-item id="my-model" src="./path/to/your/model.glb"></a-asset-item>
     </a-assets>
   </a-scene>
   ```

3. Accédez à l'objet chargé dans votre script et utilisez la fonction `getAnimations()` pour obtenir une liste des animations disponibles.

   ```javascript
   // import Three.js
   import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.145/build/three.min.js';

   // get A-Frame instance
   const scene = document.querySelector('a-scene');

   // get loaded GLTF object
   const gltf = scene.getObjectByProperty('uuid', THREE.GLTFLoader.uuidFromUri('./path/to/your/model.glb'));

   // get animations
   const animations = gltf.animations;
   console.log(animations);
   ```

   Notez que dans l'exemple ci-dessus, nous utilisons A-Frame, un framework de développement web pour les experiences en réalité virtuelle, incorporable avec Three.js. Si vous utilisez directement Three.js, instanciez le loader avec votre foncioneur de chargement de GLTF.

   ```javascript
   // import Three.js
   import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.145/build/three.min.js';

   // import GLTFLoader
   import { GLTFLoader } from 'https://cdn.jsdelivr.net/npm/three@0.145/examples/js/loaders/GLTFLoader.js';

   // get A-Scene element
